package dev.meshac.check;

import dev.meshac.config.MeshVersion;
import dev.meshac.data.PlayerData;

/**
 * Suppresses checks whose required context is unavailable (PARITY BLOCKERS in PARITY.md).
 * A gated check is NOT evaluated at all: no handle(), no VL, no heat, no enforcement, no alerts.
 *
 * Dependency metadata is BUILD-TIME static data (CheckDependencies, generated by
 * scripts/analyze_deps.py with transitive propagation over dev.meshac references) - runtime
 * source scanning does not exist in a packaged jar and direct string scans miss indirect
 * dependencies. A check with NO metadata entry fails closed: gated as if it needed every
 * unavailable context.
 */
public final class ContextGate {

	/** True once a translator-aware hook has resolved the player's real client version. */
	public static boolean clientVersionResolved(PlayerData data) {
		return data.getClientVersion() != MeshVersion.UNKNOWN;
	}

	/** False until the client-acknowledged world cache is implemented. */
	public static boolean worldCacheAvailable() {
		return false;
	}

	private static final java.util.Set<String> gatedLogged = java.util.concurrent.ConcurrentHashMap.newKeySet();

	private ContextGate() {
	}

	/**
	 * Returns true when the check must be suppressed for this player right now.
	 * Fail-closed: a check absent from the generated metadata is treated as needing both
	 * unavailable contexts and is gated.
	 */
	public static boolean isGated(String checkSimpleName, PlayerData data) {
		if (!CheckDependencies.KNOWN.contains(checkSimpleName)) {
			logOnce(checkSimpleName, "no dependency metadata (fail-closed)");
			return true;
		}
		if (CheckDependencies.NEEDS_WORLD_CACHE.contains(checkSimpleName) && !worldCacheAvailable()) {
			logOnce(checkSimpleName, "client-acknowledged world cache not implemented");
			return true;
		}
		if (CheckDependencies.NEEDS_CLIENT_VERSION.contains(checkSimpleName) && !clientVersionResolved(data)) {
			logOnce(checkSimpleName, "client version unresolved (no translator hook)");
			return true;
		}
		return false;
	}

	private static void logOnce(String check, String reason) {
		if (gatedLogged.add(check + '|' + reason)) {
			dev.meshac.MeshServices.log("[parity] check " + check + " suppressed: " + reason);
		}
	}

	/** Visible status for parity reporting. */
	public static String statusLine(String checkSimpleName, PlayerData data) {
		if (!CheckDependencies.KNOWN.contains(checkSimpleName)) return checkSimpleName + ": UNSUPPORTED (no metadata)";
		if (CheckDependencies.NEEDS_WORLD_CACHE.contains(checkSimpleName) && !worldCacheAvailable())
			return checkSimpleName + ": UNSUPPORTED (world cache)";
		if (CheckDependencies.NEEDS_CLIENT_VERSION.contains(checkSimpleName) && !clientVersionResolved(data))
			return checkSimpleName + ": UNSUPPORTED (client version)";
		return checkSimpleName + ": active";
	}
}
